import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }

// --- Sub-Component: 3D Rotating Box ---

interface BoxProps {
  text: string;
  boxColor: string;
  textColor: string;
  width: number;
  height: number;
  rotationOffset: number;
  speed: number;
  perspective: number;
}

const RotatingBox: React.FC<BoxProps> = ({
  text,
  boxColor,
  textColor,
  width,
  height,
  rotationOffset,
  speed,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Create a square cross-section for smooth rotation
  // The 'radius' from center to face is height / 2
  const translateZ = height / 2;

  // Calculate rotation
  // Full rotation every (fps / speed) frames
  // Add offset for staggered animation
  const cycleDuration = fps * (1 / speed); // frames per rotation
  
  // Linear rotation for continuous spin
  const rotation = interpolate(
    frame,
    [0, cycleDuration],
    [0, -360], // Rotate "forward" (top comes down)
    {
      extrapolateLeft: "extend",
      extrapolateRight: "extend",
    }
  );

  // Apply individual offset
  const finalRotation = rotation + rotationOffset;

  // Shared face styles
  const faceStyle: React.CSSProperties = {
    position: "absolute",
    width: width,
    height: height,
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    backgroundColor: boxColor,
    color: textColor,
    fontSize: height * 0.7, // Text size relative to box height
    fontWeight: 900,
    fontFamily: "Anton",
    border: `2px solid rgba(0,0,0,0.2)`, // Slight border for definition
    backfaceVisibility: "hidden", // Performance optimization
    // Optional: Add text stroke for style matching "SMALL"
    WebkitTextStroke: text === "SMALL" ? "2px black" : text === "STOP" || text === "PLAYING" || text === "FUCKING" ? "0px" : "0px", 
  };
  
  // Specific tweaks for text styles based on the image reference
  // The image shows very tight, bold text.
  const textStyle: React.CSSProperties = {
    lineHeight: 1,
    textTransform: "uppercase",
    textAlign: "center",
    width: "100%",
    letterSpacing: "-0.02em",
  };

  return (
    <div
      style={{
        width: width,
        height: height,
        position: "relative",
        transformStyle: "preserve-3d",
        transform: `rotateX(${finalRotation}deg)`,
      }}
    >
      {/* Front Face */}
      <div
        style={{
          ...faceStyle,
          transform: `rotateX(0deg) translateZ(${translateZ}px)`,
        }}
      >
        <span style={textStyle}>{text}</span>
      </div>

      {/* Top Face */}
      <div
        style={{
          ...faceStyle,
          transform: `rotateX(90deg) translateZ(${translateZ}px)`,
        }}
      >
        <span style={textStyle}>{text}</span>
      </div>

      {/* Back Face */}
      <div
        style={{
          ...faceStyle,
          transform: `rotateX(180deg) translateZ(${translateZ}px)`,
        }}
      >
        <span style={textStyle}>{text}</span>
      </div>

      {/* Bottom Face */}
      <div
        style={{
          ...faceStyle,
          transform: `rotateX(270deg) translateZ(${translateZ}px)`,
        }}
      >
        <span style={textStyle}>{text}</span>
      </div>
    </div>
  );
};

// --- Main Component ---



export type RotatingStacksProps = Record<string, any>;

const RotatingStacks: React.FC<RotatingStacksProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 10,
  items = [
    { text: "STOP", boxColor: "#FF9999", textColor: "#000000" },
    { text: "PLAYING", boxColor: "#CC0000", textColor: "#000000" },
    { text: "SO", boxColor: "#999999", textColor: "#FF66CC" },
    { text: "FUCKING", boxColor: "#CCFF00", textColor: "#000000" },
    { text: "SMALL", boxColor: "#0033CC", textColor: "#FF0000" },
  ],
  rotationSpeed = 0.5,
  perspective = 1000,
  staggerOffset = 20,
}) => {
  useFontLoader(["Anton"]);

  const { width, height } = useVideoConfig();

  // Logic to prevent parser errors for background
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Responsive calculations
  const boxHeight = height * 0.12; // Each box takes ~12% of screen height
  const boxWidth = width * 0.8;    // 80% width
  const gap = boxHeight * 0.4;     // Vertical gap between boxes
  
  const totalContentHeight = items.length * boxHeight + (items.length - 1) * gap;
  const startY = (height - totalContentHeight) / 2;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Anton",
        perspective: `${perspective}px`,
        overflow: "hidden", // Hide overflow if boxes rotate off-screen
      }}
    >
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: `${gap}px`,
        }}
      >
        {items.map((item, index) => {
          // Stagger calculation: Bottom items might rotate slightly behind or ahead
          // We'll offset them so they create a wave
          const offset = index * staggerOffset; 

          return (
            <RotatingBox
              key={index}
              text={item.text}
              boxColor={item.boxColor}
              textColor={item.textColor}
              width={boxWidth}
              height={boxHeight}
              rotationOffset={offset}
              speed={rotationSpeed}
              perspective={perspective}
            />
          );
        })}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default RotatingStacks;